### Step 3 — Implement the CI Validation Gate

Add a CI pipeline step that verifies sync integrity. The gate runs after checkout and before tests:

```yaml
feature:validate:
  desc: Verify all language .feature copies match canonical source
  cmds:
    - |
      $failures = @()
      Get-ChildItem -Path "docs/requirements/functional" -Recurse -Filter "*.feature" | ForEach-Object {
        $canonical = $_.FullName
        $rel = $canonical.Replace((Get-Location).Path + "\docs\requirements\functional\", "")
        $concern = Split-Path $rel -Parent
        $file = $_.Name

        $targets = @(
          "components/java/src/test/resources/features/$concern/$file",
          "components/dotnet/tests/Mmes.Common.Core.Tests/$((Get-Culture).TextInfo.ToTitleCase($concern))/$file",
          "components/rust/tests/features/$concern/$file"
        )

        foreach ($target in $targets) {
          if (-not (Test-Path $target)) {
            $failures += "MISSING: $target (canonical: $rel)"
          } elseif ((Get-FileHash $canonical).Hash -ne (Get-FileHash $target).Hash) {
            $failures += "DRIFT: $target differs from canonical $rel"
          }
        }
      }

      if ($failures.Count -gt 0) {
        $failures | ForEach-Object { Write-Error $_ }
        exit 1
      } else {
        Write-Host "All .feature copies match canonical source."
      }
```
